<div class="admin-form-grid">
    <div><label class="form-label" for="service_name_{{ $service?->id ?? 'new' }}">Name</label><input class="form-control" id="service_name_{{ $service?->id ?? 'new' }}" name="name" value="{{ old('name', $service?->name) }}" required></div>
    <div><label class="form-label" for="service_category_{{ $service?->id ?? 'new' }}">Category</label><input class="form-control" id="service_category_{{ $service?->id ?? 'new' }}" name="category" value="{{ old('category', $service?->category) }}" required></div>
    <div><label class="form-label" for="service_summary_{{ $service?->id ?? 'new' }}">Summary</label><input class="form-control" id="service_summary_{{ $service?->id ?? 'new' }}" name="summary" value="{{ old('summary', $service?->summary) }}" required></div>
    <div><label class="form-label" for="service_price_{{ $service?->id ?? 'new' }}">Starting price (LKR)</label><input class="form-control" id="service_price_{{ $service?->id ?? 'new' }}" name="price_from" type="number" min="0" value="{{ old('price_from', $service?->price_from ?? 0) }}" required></div>
    <div><label class="form-label" for="service_duration_{{ $service?->id ?? 'new' }}">Duration (minutes)</label><input class="form-control" id="service_duration_{{ $service?->id ?? 'new' }}" name="duration_minutes" type="number" min="15" max="480" value="{{ old('duration_minutes', $service?->duration_minutes ?? 30) }}" required></div>
    <div><label class="form-label" for="service_description_{{ $service?->id ?? 'new' }}">Description</label><textarea class="form-control" id="service_description_{{ $service?->id ?? 'new' }}" name="description" rows="3" required>{{ old('description', $service?->description) }}</textarea></div>
    <div class="form-check service-active"><input type="hidden" name="active" value="0"><input class="form-check-input" id="service_active_{{ $service?->id ?? 'new' }}" name="active" type="checkbox" value="1" @checked(old('active', $service?->active ?? true))><label class="form-check-label" for="service_active_{{ $service?->id ?? 'new' }}">Available to customers</label></div>
</div>